function encrypt(text, shift) {
  var out = "";
  for (var i = 0; i < text.length; i++) {
    var code = text.charCodeAt(i);
    if (code >= 97 && code <= 122) {
      out += String.fromCharCode((code - 97 + shift) % 26 + 97);
    } else if (code >= 65 && code <= 90) {
      out += String.fromCharCode((code - 65 + shift) % 26 + 65);
    } else {
      out += text.charAt(i);
    }
  }
  return out;
}

